
#src/nubra_python_sdk/trading/trading_data.py
import json

from typing import List, Optional, Union

from pydantic import ValidationError # type: ignore

from nubra_python_sdk.start_sdk import InitNubraSdk
from nubra_python_sdk.interceptor.htttpclient import BaseHttpClient
from nubra_python_sdk.interceptor.errors import NubraValidationError
from nubra_python_sdk.marketdata.market_data import MarketData
from nubra_python_sdk.portfolio.portfolio_data import NubraPortfolio
from nubra_python_sdk.trading.validation import (
    CreateIntentOrderRequest,
    ModifyIntentOrderRequest,
    CancelIntentOrderRequest,
    GetIntentOrdersResponse,
    GetFundsRequiredRequest,
    FundsRequiredResp,
    CreateIntentOrderResponse,
    IntentPriceType
)
from nubra_python_sdk.trading.trading_enum import (
    IntentValidityType,
    IntentOrderSide,
)

import logging
logger= logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
print = lambda *args, **kwargs: None





class NubraTrader(InitNubraSdk):
    """
    Fetches real-time, trading data from Nubra.
    """
    def __init__(self, client: InitNubraSdk):
        """
        Initializes the Trading Data instance using the provided Nubra SDK client.

        Args:
            client (InitNubraSdk): An authenticated instance of InitNubraSdk.
        """
        self.api_base_url = client.API_BASE_URL
        self.db_path= client.db_path
        self.totp_login = client.totp_login
        self.token_data = client.token_data
        self.env_path_login = client.env_path_login
        self.client = BaseHttpClient(self)
        self.portfolio = NubraPortfolio(client=client)

    def _url(self, path):
        """
        Constructs the full API URL for a given endpoint path.

        Args:
            path (str): Relative API path.

        Returns:
            str: Full API URL.
        """
        return f"{self.api_base_url}/{path}"

    def create_order(self, orders: Union[List[dict], dict]):
        """
        Place single order.

        It serializes the input and sends a POST request to the order creation endpoint.

        Args:
            orders: Single order to be placed.

        Returns:
            CreateOrderWrapper: A wrapped response containing a list of order confirmation data.
            dict: Error message(s) in case of validation failure.

        Raises:
            NubraValidationError: If response deserialization fails due to invalid format.

        Example:
            >>> create_order({
            ...    "ref_id": 12345,
            ...    "request_type": "ORDER_REQUEST_NEW",
            ...    "order_type": "ORDER_TYPE_MARKET",
            ...    "order_qty": 1,
            ...    "order_price": 12,// in Rupees
            ...    "order_side": "ORDER_SIDE_BUY",
            ...    "order_delivery_type":"ORDER_DELIVERY_TYPE_IDAY",
            ...    "execution_type": "STRATEGY_TYPE_MARKET"
            ...    }
        """
        if isinstance(orders, list):
            payload_dict = {"orders": orders}
        elif isinstance(orders, dict) and "orders" not in orders:
            payload_dict = {"orders": [orders]}
        else:
            payload_dict = orders

        try:
            orders = CreateIntentOrderRequest(**payload_dict)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
        
        payload= orders.model_dump(by_alias= True)
        try:
            response= self.client.request("post", self._url("sentinel/orders/create"), json= payload)
            return CreateIntentOrderResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
        
        
    def get_order(self, order_id : Union[List[int], int]):
        path = "sentinel/orders"
        single = isinstance(order_id, int)
        order_ids = [order_id] if single else order_id

        path += f"?intentOrderId={','.join(str(oid) for oid in order_ids)}"

        try:
            response = self.client.request("get", self._url(path))
            if response.json() is None:
                return [] if not single else None
            raw = GetIntentOrdersResponse(**response.json())

            result = []
            for intent_list in raw.orders.values():
                if not intent_list:
                    continue
                result += intent_list
            return result

        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

            
    def modify_orders_sentinel(self, request: Union[List[dict], dict]):
        if isinstance(request, list):
            try:
                request = ModifyIntentOrderRequest(orders=request)
            except ValidationError as ve:
                raise NubraValidationError(ve.errors())
        elif isinstance(request, dict):
            try:
                request = ModifyIntentOrderRequest(orders=[request])
            except ValidationError as ve:
                raise NubraValidationError(ve.errors())
            
        payload= request.model_dump(by_alias= True)
        try:
            response = self.client.request("post", self._url("sentinel/orders/modify"), json=payload)
            return response.json()
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
    
        
    def cancel_orders_sentinel(self, request: List[dict]):
        try:
            request = CancelIntentOrderRequest(orders=request)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
        
        payload = request.model_dump(by_alias=True, exclude_none=True)
        try:
            response = self.client.request("post", self._url("sentinel/orders/cancel"), json=payload)
            return response.json()
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
    
    def orders(self, status: Optional[str] = None, symbol: Optional[str] = None,
               delivery_type: Optional[str] = None, exchange: Optional[str] = None, strat_tags: Optional[Union[List[str], str]] = None):
        """
        Retrieve all orders placed by the user.

        V2 args (ignored in V3):
            live (bool): Return only live/open orders.
            executed (bool): Return only executed orders.
            tag (str): Filter by tag.

        V3 args (ignored in V2):
            status (str): Filter by NubraStatus — one of OPEN, EXECUTED, REJECTED,
                GTE, CANCELLED, EXPIRED.
            symbol (str): Filter by instrument symbol.
            delivery_type (str): Filter by delivery type (IDAY or CNC).
            exchange (str): Filter by exchange (NSE, BSE, MCX).

        Returns:
            GetIntentOrdersResponse (V3) or GetAllOrdersV2 (V2).

        Raises:
            NubraValidationError: If response is invalid or cannot be parsed.
        """
        path = "sentinel/orders"
        try:
            params = []
            if status:
                params.append(f"status={status}")
            if symbol:
                params.append(f"symbol={symbol}")
            if delivery_type:
                params.append(f"delivery_type={delivery_type}")
            if exchange:
                params.append(f"exchange={exchange}")
            if strat_tags:
                if isinstance(strat_tags, str):
                    strat_tags = [strat_tags] 
                params.append(f"stratTags={','.join(str(st) for st in strat_tags)}")

            if params:
                path += "?" + "&".join(params)

            try:
                response = self.client.request("get", self._url(path))
                if response.json() is None:
                    return []
                return GetIntentOrdersResponse(**response.json())
            except ValidationError as ve:
                raise NubraValidationError(ve.errors())
                
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
    
    
    def exit_all_positions(self, at_market_price : Optional[bool] = False):
        # Default behaviour is to exit at LTP; pass at_market_price=True to exit at market price.
        at_ltp = not at_market_price

        result = self.portfolio.positions()
        if not result or isinstance(result, list):
            return []
        
        open_positions = [ p for p in (result.portfolio.positions or []) if p.netQuantity and p.status == "OPEN" ]
        if not open_positions:
            return []
        
        orders = []
        for p in open_positions:
            order = {
                "refId": p.refId,
                "side": IntentOrderSide.SELL if p.orderSide == IntentOrderSide.BUY else IntentOrderSide.BUY,
                "qty": abs(p.netQuantity),
                "deliveryType": p.deliveryType,
                "priceType":IntentPriceType.MARKET if at_market_price else IntentPriceType.LIMIT,
                "executionMode": "ENTRY",
                "validityType": IntentValidityType.IOC
            }
            if at_ltp:
                order["entryPrice"] = p.lastTradedPrice
                order["validityType"] = IntentValidityType.DAY
            orders.append(order)

        return self.create_order(orders)
    
    def get_margin(self, request: dict):
        """
        Calculate the margin required for a set of trading orders.

        This method validates the input request using the `MarginRequest` Pydantic model,
        converts it into the expected payload format. If the response is valid,
        it returns a `MarginResponse` object containing various margin components like
        SPAN, exposure, delivery margin, etc.

        Parameters:
            request (dict): A dictionary representing the margin request, expected to
                            conform to the `MarginRequest` model structure. It must
                            include order details such as `ref_id`, `order_type`,
                            `order_side`, `order_qty`, and optionally `order_price`.

        Returns:
            MarginResponse: A validated Pydantic model containing detailed margin
                            requirements including SPAN, exposure, total margin,
                            delivery margin, and per-leg breakdowns.

        Raises:
            NubraValidationError: If the response from the margin API cannot be parsed
                                into a valid `MarginResponse` model.

        Example:
            >>> margin_required({
            ...     "with_portfolio": True,
            ...     "order_req": [{
            ...         "ref_id": 72329,
            ...         "request_type": "margin",
            ...         "order_type": "LIMIT",
            ...         "order_delivery_type": "INTRADAY",
            ...         "order_qty": 1,
            ...         "order_price": 123.45,
            ...         "order_side": "BUY",
            ...         "execution_type": "REGULAR"
            ...     }]
            ... })
        """
        try:
            request = GetFundsRequiredRequest(**request)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

        payload = request.model_dump(by_alias=True)
        try:
            response = self.client.request("post", self._url("sentinel/orders/funds_required"), json=payload)
            return FundsRequiredResp(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

            

